import java.util.*; public class Permutations{static void bt(String[]e,boolean[]u,List<String>p,List<List<String>>r){if(p.size()==e.length){r.add(new ArrayList<>(p));return;}for(int i=0;i<e.length;i++){if(u[i])continue;u[i]=true;p.add(e[i]);bt(e,u,p,r);p.remove(p.size()-1);u[i]=false;}}public static void main(String[]a){String[]e={"A","B","C"};List<List<String>>r=new ArrayList<>();bt(e,new boolean[e.length],new ArrayList<>(),r);System.out.println(r);}}